Трудно (точнее невозможно) повернуть экватор. Не продумано, где ядро (D=0).
Hard to turn over equator.
Where is the core?

    
        clYellow       := 'FFFF00';
        clBlue         := '0000A0';
        clOrange       := 'FF6000';
        clRed          := 'FF0000';
        clGreen        := '008000';
        clWhite        := 'FFFFFF';
        clGolden       := 'AABB20';
        clLightViolett := 'FF0080';
        clLightBlue    := '2828FF';
        clViolett      := '800080';
        clBrown        := '800000';
        clLightGreen   := '00FF00';
        clCyan         := '00DCB4';
        clPink         := 'FF69B4';
        clOlive        := '808000';
        clLime         := '00FF00';
        clKhaki        := 'F0E68C';
        clDeepSky      := '00BFFF';         
        clTeal         := '008080';    

        NN:= 5;
        K := 0.4;
        nAngle := Pi/NN;
        mm:= 0.95;

        i := 1; j := 0;
        H := K * cos(nAngle) / sqrt(cos(i * nAngle) * cos(j * nAngle));

        z := H * (1-cos(nAngle))/(1+cos(nAngle));
        for i := 0 to NN-1 do begin
            x[2*i] := K * cos(2 * nAngle * i);
            y[2*i] := K * sin(2 * nAngle * i);
            x[2*i + 1] := K * cos(2 * nAngle * (i + 0.5));
            y[2*i + 1] := K * sin(2 * nAngle * (i + 0.5));
        end;

        az := K * cos(nAngle) / H;
        for i := 0 to NN-1 do begin
            ax[i] := cos(2 * nAngle * (i + 0.5));
            ay[i] := sin(2 * nAngle * (i + 0.5));
        end;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        // Calc all Jumble Angles
        A1 := Angle(ax[0],ay[0],az, ax[1],ay[1],az, ax[4],ay[4],az);
        A2 := Angle(ax[0],ay[0],az, ax[2],ay[2],az, ax[3],ay[3],az);
    

    
        
        
        
        
        
    
    
        
    

    
        
            
